package br.com.onda;
import android.content.Context;
import android.graphics.Bitmap;
import org.junit.Test;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import javax.net.ssl.*;
@androidx.media3.common.util.UnstableApi
public class ConnectSessionTest {
 static class Events implements ConnectSession.Listener {
  final CompletableFuture<ConnectProtocol.Pair> paired=new CompletableFuture<>();final CompletableFuture<Boolean> result=new CompletableFuture<>();final boolean accept;volatile boolean offered;int completed;
  Events(boolean accept){this.accept=accept;}public void pair(ConnectProtocol.Pair pair){paired.complete(pair);}public void offer(List<ConnectProtocol.FileInfo> files,java.util.function.Consumer<Boolean> answer){offered=true;answer.accept(accept);}public void progress(String text,long done,long total){}public void finished(boolean success,int completed,String message){this.completed=completed;result.complete(success);}
 }
 static class Disk implements ConnectSession.Sink {
  final List<File> committed=new ArrayList<>(),all=new ArrayList<>();final File dir;
  Disk()throws Exception{Context c=getInstrumentation().getTargetContext();dir=new File(c.getCacheDir(),"conecta-test-"+UUID.randomUUID());assertTrue(dir.mkdirs());}
  public ConnectSession.Target create(ConnectProtocol.FileInfo info)throws Exception{File file=new File(dir,info.name);all.add(file);FileOutputStream out=new FileOutputStream(file);return new ConnectSession.Target(){public OutputStream stream(){return out;}public void commit(){committed.add(file);}public void abort(){file.delete();}};}
  void cleanup(){for(File f:all)f.delete();dir.delete();}
 }
 @Test public void realTlsTransfersTwoFilesWithHashes()throws Exception{SSLContext serverTls=ConnectTls.server();Disk disk=new Disk();Events receiver=new Events(true),sender=new Events(true);ConnectSession receiving=new ConnectSession(receiver),sending=new ConnectSession(sender);ExecutorService worker=Executors.newSingleThreadExecutor();try{worker.submit(()->receiving.receive(serverTls,"127.0.0.1",pin(),disk));ConnectProtocol.Pair pair=receiver.paired.get(15,TimeUnit.SECONDS);byte[] audio=new byte[240000],pdf="%PDF-test Onda Conecta".getBytes(java.nio.charset.StandardCharsets.UTF_8);new Random(7).nextBytes(audio);List<byte[]> bytes=Arrays.asList(audio,pdf);sending.send(ConnectTls.client(pair.pin),pair,Arrays.asList(new ConnectProtocol.FileInfo("Aula.mp3","audio/mpeg",audio.length),new ConnectProtocol.FileInfo("Guia.pdf","application/pdf",pdf.length)),i->new ByteArrayInputStream(bytes.get(i)));assertTrue("Sender: "+trace(sending.failure)+"; receiver: "+trace(receiving.failure),sender.result.get(10,TimeUnit.SECONDS));assertTrue(receiver.result.get(10,TimeUnit.SECONDS));assertEquals(2,receiver.completed);assertEquals(2,disk.committed.size());for(int i=0;i<2;i++)assertArrayEquals(bytes.get(i),java.nio.file.Files.readAllBytes(disk.committed.get(i).toPath()));}finally{receiving.close();sending.close();worker.shutdownNow();disk.cleanup();}}
 static String trace(Exception error){if(error==null)return "none";StringWriter text=new StringWriter();error.printStackTrace(new PrintWriter(text));return text.toString();}
 static String pin(){try{return ConnectTls.pin();}catch(Exception e){throw new IllegalStateException(e);}}
 @Test public void refusalCreatesNoFiles()throws Exception{SSLContext tls=ConnectTls.server();Disk disk=new Disk();Events receiver=new Events(false),sender=new Events(true);ConnectSession receiving=new ConnectSession(receiver),sending=new ConnectSession(sender);ExecutorService worker=Executors.newSingleThreadExecutor();try{worker.submit(()->receiving.receive(tls,"127.0.0.1",pin(),disk));ConnectProtocol.Pair pair=receiver.paired.get(10,TimeUnit.SECONDS);sending.send(ConnectTls.client(pair.pin),pair,Arrays.asList(new ConnectProtocol.FileInfo("A.pdf","application/pdf",3)),i->new ByteArrayInputStream(new byte[3]));assertFalse(sender.result.get(10,TimeUnit.SECONDS));assertFalse(receiver.result.get(10,TimeUnit.SECONDS));assertTrue(receiver.offered);assertTrue(disk.all.isEmpty());}finally{receiving.close();sending.close();worker.shutdownNow();disk.cleanup();}}
 @Test public void wrongQrCertificateCannotTransfer()throws Exception{SSLContext tls=ConnectTls.server();Disk disk=new Disk();Events receiver=new Events(true),sender=new Events(true);ConnectSession receiving=new ConnectSession(receiver),sending=new ConnectSession(sender);ExecutorService worker=Executors.newSingleThreadExecutor();try{worker.submit(()->receiving.receive(tls,"127.0.0.1",pin(),disk));ConnectProtocol.Pair pair=receiver.paired.get(10,TimeUnit.SECONDS);sending.send(ConnectTls.client(ConnectProtocol.secret()),pair,Arrays.asList(new ConnectProtocol.FileInfo("A.pdf","application/pdf",3)),i->new ByteArrayInputStream(new byte[3]));assertFalse(sender.result.get(10,TimeUnit.SECONDS));assertTrue(disk.all.isEmpty());}finally{receiving.close();sending.close();worker.shutdownNow();disk.cleanup();}}
 @Test public void damagedFileIsDeletedBeforeConfirmation()throws Exception{SSLContext tls=ConnectTls.server();Disk disk=new Disk();Events receiver=new Events(true);ConnectSession receiving=new ConnectSession(receiver);ExecutorService worker=Executors.newSingleThreadExecutor();try{worker.submit(()->receiving.receive(tls,"127.0.0.1",pin(),disk));ConnectProtocol.Pair pair=receiver.paired.get(10,TimeUnit.SECONDS);try(SSLSocket socket=(SSLSocket)ConnectTls.client(pair.pin).getSocketFactory().createSocket("127.0.0.1",pair.port)){socket.setSoTimeout(10000);DataOutputStream out=new DataOutputStream(socket.getOutputStream());DataInputStream in=new DataInputStream(socket.getInputStream());ConnectProtocol.offer(out,pair.token,Arrays.asList(new ConnectProtocol.FileInfo("A.pdf","application/pdf",3)));assertTrue(in.readBoolean());out.write(new byte[]{1,2,3});out.write(new byte[32]);out.flush();assertFalse(receiver.result.get(10,TimeUnit.SECONDS));assertTrue(disk.committed.isEmpty());assertEquals(1,disk.all.size());assertFalse(disk.all.get(0).exists());}}finally{receiving.close();worker.shutdownNow();disk.cleanup();}}
 @Test public void generatedQrIsReadWithoutNetwork()throws Exception{ConnectProtocol.Pair pair=new ConnectProtocol.Pair("192.168.1.10",34567,ConnectProtocol.secret(),ConnectProtocol.secret());Bitmap bitmap=ConnectQr.make(pair.code(),640);try{String code=ConnectQr.read(bitmap);assertEquals(pair.code(),code);assertEquals(pair.pin,ConnectProtocol.Pair.parse(code).pin);}finally{bitmap.recycle();}}

}
